def transform(grid):
    # Replace isolated outlier pixels with the local color pattern. A small
    # marker component embedded in a large object is erased to the background.
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(comp)==1 and col not in (grid[0][0],):
                y,x=comp[0]
                # choose adjacent region majority, preferring the surrounding background
                neigh=[grid[yy][xx] for yy in range(max(0,y-1),min(h,y+2)) for xx in range(max(0,x-1),min(w,x+2)) if (yy,xx)!=(y,x)]
                if neigh:
                    vals={v:neigh.count(v) for v in set(neigh)}
                    out[y][x]=max(vals,key=vals.get)
    return out
